export const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

export const MIN_SIZE = 32;
export const MAX_SIZE = 1920;
export const DEFAULT_SIZE = 128;

export const MIN_SPEED = 0.25;
export const MAX_SPEED = 4;

export function isValidSize(n: number) {
  return Number.isInteger(n) && n >= MIN_SIZE && n <= MAX_SIZE;
}

export const INVALID_SIZE_MESSAGE = `Invalid size. Must be an integer between ${MIN_SIZE} and ${MAX_SIZE}.`;

/**
 * Deterministic renders (a given `/api/pixabot/{id}?...` URL always
 * produces the same bytes at any point in time, but sprite art can change
 * when we ship new part variants). 1-day fresh window for CDN / browser
 * cache, then 7 days of stale-while-revalidate — art updates propagate
 * within a day without a manual CDN purge, but repeat loads stay fast.
 * Manual purge still wins if we need instant rollout.
 */
export const DETERMINISTIC_CACHE =
  "public, max-age=86400, stale-while-revalidate=604800";

export function optionsResponse() {
  return new Response(null, { status: 204, headers: CORS_HEADERS });
}

export function imageResponse(buffer: Buffer, contentType: string) {
  return new Response(new Uint8Array(buffer), {
    headers: {
      "Content-Type": contentType,
      "Cache-Control": DETERMINISTIC_CACHE,
      "CDN-Cache-Control": DETERMINISTIC_CACHE,
      ...CORS_HEADERS,
    },
  });
}

import { type NextRequest } from "next/server";
import { isValidId } from "@pixabots/core";
import { generateOgImage } from "@/lib/og-image";
import { CORS_HEADERS, optionsResponse, imageResponse } from "@/lib/api";
import { checkRate, clientKey, isSameOrigin } from "@/lib/rate-limit";
import { parseIdsCsv } from "@/lib/ids";
import { normalizeHex } from "@/lib/palette";

const OG_LIMIT = 60;
const OG_WINDOW_MS = 60_000;

const MAX_TITLE_LEN = 60;
const MAX_SUBTITLE_LEN = 100;
const MAX_SEED_LEN = 80;

export const OPTIONS = optionsResponse;

function clampText(v: string | null, max: number): string | undefined {
  if (v == null) return undefined;
  return v.length > max ? v.slice(0, max) : v;
}

function parsePalette(
  params: URLSearchParams
): { hue?: number; saturate?: number } | undefined {
  const hueRaw = params.get("hue");
  const satRaw = params.get("saturate");
  let hue: number | undefined;
  let saturate: number | undefined;
  if (hueRaw !== null) {
    const n = Number(hueRaw);
    if (Number.isFinite(n)) hue = ((Math.round(n) % 360) + 360) % 360;
  }
  if (satRaw !== null) {
    const n = Number(satRaw);
    if (Number.isFinite(n)) saturate = Math.max(0, Math.min(4, n));
  }
  if (hue === undefined && saturate === undefined) return undefined;
  return { hue, saturate };
}

export async function GET(request: NextRequest) {
  const rate = isSameOrigin(request)
    ? { allowed: true, remaining: OG_LIMIT, resetSeconds: 60, limit: OG_LIMIT }
    : checkRate(`og:${clientKey(request)}`, OG_LIMIT, OG_WINDOW_MS);
  if (!rate.allowed) {
    return Response.json(
      { error: `Rate limit exceeded. Try again in ${rate.resetSeconds}s.` },
      {
        status: 429,
        headers: {
          ...CORS_HEADERS,
          "Retry-After": String(rate.resetSeconds),
          "X-RateLimit-Limit": String(rate.limit),
          "X-RateLimit-Remaining": "0",
          "X-RateLimit-Reset": String(Math.floor(Date.now() / 1000) + rate.resetSeconds),
        },
      }
    );
  }

  const params = request.nextUrl.searchParams;
  const type = params.get("type") ?? "grid";
  const title = clampText(params.get("title"), MAX_TITLE_LEN) ?? "Pixabots";
  const subtitle = clampText(params.get("subtitle"), MAX_SUBTITLE_LEN);
  const palette = parsePalette(params);
  const bgRaw = params.get("bg");
  const bg = bgRaw ? normalizeHex(bgRaw) ?? undefined : undefined;

  try {
    if (type === "single") {
      const id = params.get("id");
      if (!id || !isValidId(id)) {
        return Response.json(
          { error: "Missing or invalid id" },
          { status: 400, headers: CORS_HEADERS }
        );
      }
      const buffer = await generateOgImage({ type: "single", id, title, subtitle, palette, bg });
      return imageResponse(buffer, "image/png");
    }

    if (type === "compare") {
      const ids = parseIdsCsv(params.get("ids"), 6);
      if (ids.length === 0) {
        return Response.json(
          { error: "Missing or invalid ids (expected comma-separated list of up to 6 valid pixabot IDs)" },
          { status: 400, headers: CORS_HEADERS }
        );
      }
      const buffer = await generateOgImage({ type: "compare", ids, title, subtitle, palette, bg });
      return imageResponse(buffer, "image/png");
    }

    if (type !== "grid") {
      return Response.json(
        { error: "type must be 'grid', 'single', or 'compare'" },
        { status: 400, headers: CORS_HEADERS }
      );
    }

    const seed = clampText(params.get("seed"), MAX_SEED_LEN) ?? title;
    const buffer = await generateOgImage({ type: "grid", title, subtitle, seed, palette, bg });
    return imageResponse(buffer, "image/png");
  } catch (e) {
    return Response.json(
      { error: e instanceof Error ? e.message : "OG render failed" },
      { status: 500, headers: CORS_HEADERS }
    );
  }
}

