import { type NextRequest } from "next/server";
import { decode, isValidId, resolve, randomId } from "@pixabots/core";
import {
  CORS_HEADERS,
  optionsResponse,
  isValidSize,
  INVALID_SIZE_MESSAGE,
  DEFAULT_SIZE,
  DETERMINISTIC_CACHE,
} from "@/lib/api";
import { normalizeHex } from "@/lib/palette";

export const OPTIONS = optionsResponse;

const MAX_IDS = 100;

export async function GET(request: NextRequest) {
  const params = request.nextUrl.searchParams;
  const sizeParam = params.get("size");
  const size = sizeParam ? Number(sizeParam) : DEFAULT_SIZE;

  if (!isValidSize(size)) {
    return Response.json(
      { error: INVALID_SIZE_MESSAGE },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  const idsRaw = params.get("ids");
  const countParam = params.get("count");
  const count = countParam ? Number(countParam) : 0;

  let ids: string[] = [];

  if (idsRaw) {
    ids = idsRaw.split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
  } else if (Number.isInteger(count) && count > 0) {
    ids = Array.from({ length: Math.min(count, MAX_IDS) }, () => randomId());
  } else {
    return Response.json(
      {
        error:
          "Provide either `ids=a,b,c,...` (up to 100) or `count=N` for N random pixabots.",
      },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  if (ids.length === 0) {
    return Response.json(
      { error: "No IDs provided." },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  if (ids.length > MAX_IDS) {
    return Response.json(
      { error: `Too many IDs. Max is ${MAX_IDS}.` },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  const invalid = ids.filter((id) => !isValidId(id));
  if (invalid.length > 0) {
    return Response.json(
      { error: `Invalid IDs: ${invalid.join(", ")}` },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  // Forward palette + bg into the per-bot URLs so consumers get recolored
  // variants without having to append the params themselves.
  const paletteParts: string[] = [];
  const hueRaw = params.get("hue");
  const satRaw = params.get("saturate");
  const bgRaw = params.get("bg");
  if (hueRaw !== null) {
    const n = Number(hueRaw);
    if (Number.isFinite(n)) paletteParts.push(`hue=${((Math.round(n) % 360) + 360) % 360}`);
  }
  if (satRaw !== null) {
    const n = Number(satRaw);
    if (Number.isFinite(n)) paletteParts.push(`saturate=${Math.max(0, Math.min(4, n))}`);
  }
  if (bgRaw !== null) {
    const bg = normalizeHex(bgRaw);
    if (bg) paletteParts.push(`bg=${encodeURIComponent(bg)}`);
  }
  const pal = paletteParts.length ? `&${paletteParts.join("&")}` : "";

  const origin = request.nextUrl.origin;
  const pixabots = ids.map((id) => {
    const combo = decode(id);
    return {
      id,
      combo,
      parts: resolve(combo),
      png: `${origin}/api/pixabot/${id}?size=${size}${pal}`,
      gif: `${origin}/api/pixabot/${id}?size=${size}&animated=true${pal}`,
    };
  });

  const deterministic = Boolean(idsRaw);
  return Response.json(
    { count: pixabots.length, pixabots },
    {
      headers: {
        ...CORS_HEADERS,
        "Cache-Control": deterministic ? DETERMINISTIC_CACHE : "no-store",
      },
    }
  );
}

import { type NextRequest } from "next/server";
import { randomId, decode, resolve } from "@pixabots/core";
import {
  CORS_HEADERS,
  optionsResponse,
  isValidSize,
  INVALID_SIZE_MESSAGE,
  MIN_SPEED,
  MAX_SPEED,
} from "@/lib/api";

export const dynamic = "force-dynamic";

export const OPTIONS = optionsResponse;

const FORWARDED_PARAMS = ["size", "animated", "speed", "webp", "hue", "saturate", "bg"] as const;

export async function GET(request: NextRequest) {
  const params = request.nextUrl.searchParams;
  const format = params.get("format");
  const id = randomId();

  if (format === "json") {
    const origin = request.nextUrl.origin;
    const combo = decode(id);
    return Response.json(
      {
        id,
        combo,
        parts: resolve(combo),
        png: `${origin}/api/pixabot/${id}`,
        gif: `${origin}/api/pixabot/${id}?animated=true`,
      },
      { headers: { ...CORS_HEADERS, "Cache-Control": "no-store" } }
    );
  }

  const sizeParam = params.get("size");
  if (sizeParam !== null && !isValidSize(Number(sizeParam))) {
    return Response.json(
      { error: INVALID_SIZE_MESSAGE },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  const speedParam = params.get("speed");
  if (speedParam !== null) {
    const parsed = Number(speedParam);
    if (!Number.isFinite(parsed)) {
      return Response.json(
        { error: `Invalid speed. Must be a number between ${MIN_SPEED} and ${MAX_SPEED}.` },
        { status: 400, headers: CORS_HEADERS }
      );
    }
  }

  const target = new URL(`/api/pixabot/${id}`, request.url);
  for (const key of FORWARDED_PARAMS) {
    const value = params.get(key);
    if (value !== null) target.searchParams.set(key, value);
  }

  return new Response(null, {
    status: 302,
    headers: {
      Location: target.toString(),
      "Cache-Control": "no-store",
      ...CORS_HEADERS,
    },
  });
}

import { type NextRequest } from "next/server";
import { decode, isValidId, resolve } from "@pixabots/core";
import {
  renderPixabot,
  renderAnimatedPixabot,
  renderPixabotSvg,
  RenderError,
} from "@/lib/render";
import {
  CORS_HEADERS,
  optionsResponse,
  imageResponse,
  isValidSize,
  INVALID_SIZE_MESSAGE,
  DEFAULT_SIZE,
  MIN_SPEED,
  MAX_SPEED,
  DETERMINISTIC_CACHE,
} from "@/lib/api";
import { checkRate, clientKey, isSameOrigin } from "@/lib/rate-limit";
import { normalizeHex } from "@/lib/palette";

// Per-IP rate limit for animated renders (GIF / WebP are 5–50× costlier
// than PNG). Limits per minute per lambda instance. Same-origin traffic
// (our own /browse grid, etc.) bypasses this — see isSameOrigin below.
const ANIMATED_LIMIT = 120;
const ANIMATED_WINDOW_MS = 60_000;

export const OPTIONS = optionsResponse;

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const format = request.nextUrl.searchParams.get("format");
  const sizeParam = request.nextUrl.searchParams.get("size");
  const size = sizeParam ? Number(sizeParam) : DEFAULT_SIZE;

  if (!isValidId(id)) {
    return Response.json(
      { error: "Invalid pixabot ID" },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  if (!isValidSize(size)) {
    return Response.json(
      { error: INVALID_SIZE_MESSAGE },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  const combo = decode(id);
  const animated = request.nextUrl.searchParams.get("animated") === "true";
  const speedParam = request.nextUrl.searchParams.get("speed");

  // Palette transform (applies to raster output only)
  const hueParam = request.nextUrl.searchParams.get("hue");
  const saturateParam = request.nextUrl.searchParams.get("saturate");
  let hue: number | undefined;
  let saturate: number | undefined;
  if (hueParam !== null) {
    const h = Number(hueParam);
    if (!Number.isFinite(h)) {
      return Response.json(
        { error: "Invalid hue. Must be a number in degrees (0–359)." },
        { status: 400, headers: CORS_HEADERS }
      );
    }
    hue = ((Math.round(h) % 360) + 360) % 360;
  }
  if (saturateParam !== null) {
    const s = Number(saturateParam);
    if (!Number.isFinite(s) || s < 0 || s > 4) {
      return Response.json(
        { error: "Invalid saturate. Must be a number between 0 and 4." },
        { status: 400, headers: CORS_HEADERS }
      );
    }
    saturate = s;
  }
  const palette = hue !== undefined || saturate !== undefined ? { hue, saturate } : undefined;

  // Background color (flattens transparent pixels). Accepts #rrggbb.
  const bgParam = request.nextUrl.searchParams.get("bg");
  let bg: string | undefined;
  if (bgParam !== null) {
    const normalized = normalizeHex(bgParam);
    if (!normalized) {
      return Response.json(
        { error: "Invalid bg. Must be a #rrggbb hex color." },
        { status: 400, headers: CORS_HEADERS }
      );
    }
    bg = normalized;
  }
  let speed = 1;
  if (speedParam !== null) {
    const parsed = Number(speedParam);
    if (!Number.isFinite(parsed)) {
      return Response.json(
        { error: `Invalid speed. Must be a number between ${MIN_SPEED} and ${MAX_SPEED}.` },
        { status: 400, headers: CORS_HEADERS }
      );
    }
    speed = Math.min(MAX_SPEED, Math.max(MIN_SPEED, parsed));
  }

  if (format === "json") {
    const origin = request.nextUrl.origin;
    return Response.json(
      {
        id,
        combo,
        parts: resolve(combo),
        png: `${origin}/api/pixabot/${id}?size=${size}`,
        gif: `${origin}/api/pixabot/${id}?size=${size}&animated=true`,
      },
      { headers: CORS_HEADERS }
    );
  }

  try {
    if (format === "svg") {
      const svg = await renderPixabotSvg(combo, size, bg);
      return new Response(svg, {
        headers: {
          "Content-Type": "image/svg+xml; charset=utf-8",
          "Cache-Control": DETERMINISTIC_CACHE,
          "CDN-Cache-Control": DETERMINISTIC_CACHE,
          ...CORS_HEADERS,
        },
      });
    }
    if (animated) {
      const rate = isSameOrigin(request)
        ? { allowed: true, remaining: ANIMATED_LIMIT, resetSeconds: 60, limit: ANIMATED_LIMIT }
        : checkRate(`animated:${clientKey(request)}`, ANIMATED_LIMIT, ANIMATED_WINDOW_MS);
      if (!rate.allowed) {
        return Response.json(
          { error: `Rate limit exceeded. Try again in ${rate.resetSeconds}s.` },
          {
            status: 429,
            headers: {
              ...CORS_HEADERS,
              "Retry-After": String(rate.resetSeconds),
              "X-RateLimit-Limit": String(rate.limit),
              "X-RateLimit-Remaining": "0",
              "X-RateLimit-Reset": String(Math.floor(Date.now() / 1000) + rate.resetSeconds),
            },
          }
        );
      }
      const wantsWebp = request.nextUrl.searchParams.get("webp") === "true";
      const outFormat = wantsWebp ? "webp" : "gif";
      const buf = await renderAnimatedPixabot(combo, size, speed, outFormat, palette, bg);
      return imageResponse(buf, wantsWebp ? "image/webp" : "image/gif");
    }
    return imageResponse(await renderPixabot(combo, size, palette, bg), "image/png");
  } catch (e) {
    const status = e instanceof RenderError ? e.status : 500;
    const message = e instanceof RenderError ? e.message : "Render failed";
    return Response.json(
      { error: message },
      { status, headers: CORS_HEADERS }
    );
  }
}

